func testConcurrentLocalCacheExport(t *testing.T, sb integration.Sandbox) {
	integration.SkipOnPlatform(t, "windows")
	workers.CheckFeatureCompat(t, sb, workers.FeatureCacheExport, workers.FeatureCacheBackendLocal)

	ctx, cancel := context.WithTimeoutCause(sb.Context(), time.Minute, errors.New("concurrent local cache export timed out"))
	defer cancel()

	c, err := New(ctx, sb.Address())
	require.NoError(t, err)
	defer c.Close()

	// Export a single scratch-mounted layer in the default min mode so both
	// exports contend on the same ref before either writes config or manifest.
	st := llb.Image("busybox:latest").Run(llb.Shlex("sh -c 'echo shared > /out/payload'")).AddMount("/out", llb.Scratch())
	def, err := st.Marshal(ctx)
	require.NoError(t, err)

	dir := t.TempDir()
	opened := make(chan struct{}, 2)
	blocked := make(chan struct{}, 1)
	releases := [2]chan struct{}{make(chan struct{}), make(chan struct{})}
	completed := make(chan error, 2)
	eg, ctx := errgroup.WithContext(ctx)
	for i := range 2 {
		store, err := newLocalCacheStore(dir)
		require.NoError(t, err)
		s, err := session.NewSession(ctx, "")
		require.NoError(t, err)
		t.Cleanup(func() { require.NoError(t, s.Close()) })
		s.Allow(sessioncontent.NewAttachable(map[string]content.Store{
			"local:" + dir: &gatedCacheStore{Store: store, opened: opened, blocked: blocked, release: releases[i]},
		}))
		eg.Go(func() error { return s.Run(ctx, c.Dialer()) })
		eg.Go(func() error {
			defer s.Close()
			_, err := c.Solve(ctx, def, SolveOpt{
				SharedSession:         s,
				SessionPreInitialized: true,
				CacheExports: []CacheOptionsEntry{{Type: "local", Attrs: map[string]string{
					"dest": dir,
					"tag":  fmt.Sprintf("export-%d", i),
				}}},
			}, nil)
			completed <- err
			return err
		})
		if i == 0 {
			select {
			case <-opened:
			case <-ctx.Done():
				t.Fatal(context.Cause(ctx))
			}
		}
	}
	done := make(chan error, 1)
	go func() { done <- eg.Wait() }()

	// The first export owns the ingest. The second must retry rather than
	// opening and modifying the same temporary files.
	select {
	case <-blocked:
	case <-opened:
		t.Fatal("second export opened an active ingest")
	case <-ctx.Done():
		t.Fatal(context.Cause(ctx))
	}

	entries, err := os.ReadDir(filepath.Join(dir, "ingest"))
	require.NoError(t, err)
	require.Len(t, entries, 1, "exports of the same reference must reuse its ingest")
	// Index updates use a non-blocking lock. Delay the second export's retry
	// until the first has published its index entry.
	for _, release := range releases {
		close(release)
		require.NoError(t, <-completed)
	}
	require.NoError(t, <-done)

	dt, err := os.ReadFile(filepath.Join(dir, "index.json"))
	require.NoError(t, err)
	var index ocispecs.Index
	require.NoError(t, json.Unmarshal(dt, &index))
	require.Len(t, index.Manifests, 2)

	store, err := contentlocal.NewStore(dir)
	require.NoError(t, err)

	for _, desc := range index.Manifests {
		dt, err := content.ReadBlob(sb.Context(), store, desc)
		require.NoError(t, err)
		var manifest ocispecs.Manifest
		require.NoError(t, json.Unmarshal(dt, &manifest))
		for _, blob := range append(manifest.Layers, manifest.Config) {
			dt, err := content.ReadBlob(sb.Context(), store, blob)
			require.NoError(t, err)
			require.Equal(t, blob.Digest, blob.Digest.Algorithm().FromBytes(dt))
		}
	}
}

// gatedCacheStore pauses the first writer so two exports can overlap without
// relying on scheduling or a large payload to keep an ingest active.
type gatedCacheStore struct {
	content.Store
	opened  chan<- struct{}
	blocked chan<- struct{}
	release <-chan struct{}
	paused  atomic.Bool
}

func (s *gatedCacheStore) Writer(ctx context.Context, opts ...content.WriterOpt) (content.Writer, error) {
	w, err := s.Store.Writer(ctx, opts...)
	if err != nil {
		if errors.Is(err, cerrdefs.ErrUnavailable) {
			select {
			case s.blocked <- struct{}{}:
			default:
			}
			select {
			case <-s.release:
			case <-ctx.Done():
				return nil, context.Cause(ctx)
			}
		}
		return nil, err
	}
	if s.paused.CompareAndSwap(false, true) {
		s.opened <- struct{}{}
		select {
		case <-s.release:
		case <-ctx.Done():
			w.Close()
			return nil, context.Cause(ctx)
		}
	}
	return w, nil
}

func testBasicAzblobCacheImportExport(t *testing.T, sb integration.Sandbox) {
	integration.SkipOnPlatform(t, "windows")
	workers.CheckFeatureCompat(t, sb,
		workers.FeatureCacheExport,
		workers.FeatureCacheImport,
		workers.FeatureCacheBackendAzblob,
	)

	opts := helpers.AzuriteOpts{
		AccountName: "azblobcacheaccount",
		AccountKey:  base64.StdEncoding.EncodeToString([]byte("azblobcacheaccountkey")),
	}

	azAddr, cleanup, err := helpers.NewAzuriteServer(t, sb, opts)
	require.NoError(t, err)
	defer cleanup()

	im := CacheOptionsEntry{
		Type: "azblob",
		Attrs: map[string]string{
			"account_url":       azAddr,
			"account_name":      opts.AccountName,
			"secret_access_key": opts.AccountKey,
			"container":         "cachecontainer",
		},
	}
	ex := CacheOptionsEntry{
		Type: "azblob",
		Attrs: map[string]string{
			"account_url":       azAddr,
			"account_name":      opts.AccountName,
			"secret_access_key": opts.AccountKey,
			"container":         "cachecontainer",
		},
	}

	cred, err := azblob.NewSharedKeyCredential(opts.AccountName, opts.AccountKey)
	require.NoError(t, err)
	azClient, err := azblob.NewClientWithSharedKeyCredential(azAddr, cred, nil)
	require.NoError(t, err)
	readBlob := func(t *testing.T, name string) []byte {
		t.Helper()
		resp, err := azClient.DownloadStream(sb.Context(), "cachecontainer", name, nil)
		require.NoError(t, err)
		defer resp.Body.Close()
		dt, err := io.ReadAll(resp.Body)
		require.NoError(t, err)
		return dt
	}

	for _, tc := range []struct {
		name  string
		comp  compression.Type
		frame ctdcompression.Compression
	}{
		{
			name:  "default",
			comp:  compression.Gzip,
			frame: ctdcompression.Gzip,
		},
		{
			name:  "zstd",
			comp:  compression.Zstd,
			frame: ctdcompression.Zstd,
		},
		{
			name:  "uncompressed",
			comp:  compression.Uncompressed,
			frame: ctdcompression.Uncompressed,
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			im.Attrs["name"] = tc.name
			ex.Attrs["name"] = tc.name
			if tc.name != "default" {
				ex.Attrs["compression"] = tc.comp.String()
				ex.Attrs["force-compression"] = "true"
			}
			testBasicCacheImportExport(t, sb, []CacheOptionsEntry{im}, []CacheOptionsEntry{ex})

			var config cacheimporttypes.CacheConfig
			require.NoError(t, json.Unmarshal(readBlob(t, "manifests/"+tc.name), &config))
			require.NotEmpty(t, config.Layers)
			for _, layer := range config.Layers {
				require.NotNil(t, layer.Annotations)
				require.True(t, compression.IsMediaType(tc.comp, layer.Annotations.MediaType))
				blob := readBlob(t, "blobs/"+layer.Blob.String())
				require.Equal(t, tc.frame, ctdcompression.DetectCompression(blob))
			}
		})
	}
}

func testBasicCacheImportExport(t *testing.T, sb integration.Sandbox, cacheOptionsEntryImport, cacheOptionsEntryExport []CacheOptionsEntry) {
	c, err := New(sb.Context(), sb.Address())
	require.NoError(t, err)
	defer c.Close()

	imgName := integration.UnixOrWindows("busybox:latest", "nanoserver:latest")
	busybox := llb.Image(imgName)
	st := integration.UnixOrWindows(llb.Scratch(), llb.Image(imgName))

	run := func(cmd string) {
		baseState := integration.UnixOrWindows(busybox, st)
		st = baseState.Run(llb.Shlex(cmd), llb.Dir("/wd")).AddMount("/wd", st)
	}

	run(integration.UnixOrWindows(
		`sh -c "echo -n foobar > const"`,
		`cmd /C echo foobar > const`,
	))
