		deps = append(deps, []solver.CacheLink{{Src: base}})
		_, ok, err = cc.Add(outputKey(dgst("run"), 0), deps, []solver.CacheExportResult{{
			CreatedAt: time.Now(),
			Result:    &solver.Remote{Descriptors: chain, Provider: p},
