	dir := t.TempDir()
	attrs := map[string]string{"dest": dir, "tenant": "team-a", "tag": "v1"}
	opts, err := parseCacheOptions(context.Background(), false, SolveOpt{
		CacheExports: []CacheOptionsEntry{{Type: "local", Attrs: attrs}},
	})
	require.NoError(t, err)

	expected, err := localCacheTag(attrs)
	require.NoError(t, err)
	require.Equal(t, expected, opts.storesToUpdate[dir].tag)
}

